import requests

def fetch_weather(city):
    url = 'https://api.example.com/weather?q=' + city
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print('Unable to retrieve weather data:', e)
        return None

fetch_weather('Paris')

import requests

def parse_weather(data):
    if not isinstance(data, dict):
        raise ValueError('Invalid response format')
    if 'weather' not in data or not data['weather']:
        raise ValueError('Weather list is missing')
    return data['weather'][0]['description']

resp = requests.get('https://api.example.com/weather?q=Tokyo')
result = parse_weather(resp.json())
print(result)

